/* ---------- Costbook Material per gudang asal (Rp/kg) — FR-19/NFR-07b ---------- */
const COSTBOOK = M ? M.COSTBOOK : { prod2: 14500, wip: 14200, hold: 13800 };

/* ---------- Data hasil produksi (dummy, seolah dari Laporan Produksi) ---------- */
