/* ============================================================
   costbook.js — Master Costbook Material (nilai/kg per material × gudang).
   Sumber data: window.MOCK.costbook (default seed + override localStorage).
   Menyimpan perubahan agar dipakai halaman HPP (FR-19 / NFR-07b).
   ============================================================ */
(() => {
  "use strict";

  const M = window.MOCK;
  const $ = (s, r = document) => r.querySelector(s);
  const num = (v) => { const n = parseFloat(v); return isNaN(n) ? null : n; };
  const rp = (n) => (n == null ? "—" : "Rp " + Math.round(n).toLocaleString("id-ID"));

  const WAREHOUSES = M.COSTBOOK_WAREHOUSES;   // [{key,label}]
  const MATERIALS = M.COSTBOOK_MATERIALS;     // [nama material]

  // Working copy tabel: { material: { gudangKey: nilai|null } }
  let table = M.costbook.all();
  let dirty = false;

  function markDirty(state) {
    dirty = state;
    const badge = $("#saveStatus");
    if (state) {
      badge.textContent = "Perubahan belum disimpan";
      badge.className = "badge badge--draft";
    } else {
      badge.textContent = "Tersimpan";
      badge.className = "badge badge--done";
    }
  }

  function renderHead() {
    const row = $("#cbHeadRow");
    // kolom pertama "Material" sudah ada di HTML; tambah kolom gudang
    row.innerHTML =
      `<th>Material</th>` +
      WAREHOUSES.map((w) => `<th class="num">${w.label}<br /><small>Rp/kg</small></th>`).join("");
  }

  function renderBody() {
    const body = $("#costbookTable tbody");
    body.innerHTML = MATERIALS.map((mat) => {
      const cells = WAREHOUSES.map((w) => {
        const v = table[mat] ? table[mat][w.key] : null;
        return `<td class="num">
          <input type="number" min="0" step="1" class="cb-in"
                 data-material="${encodeURIComponent(mat)}" data-gudang="${w.key}"
                 value="${v != null ? v : ""}" placeholder="—" />
        </td>`;
      }).join("");
      return `<tr><td><strong>${mat}</strong></td>${cells}</tr>`;
    }).join("");
  }

  function onInput(e) {
    const t = e.target;
    if (!t.classList || !t.classList.contains("cb-in")) return;
    const mat = decodeURIComponent(t.dataset.material);
    const g = t.dataset.gudang;
    if (!table[mat]) table[mat] = {};
    table[mat][g] = num(t.value);
    markDirty(true);
  }

  let toastTimer = null;
  function toast(msg, kind = "") {
    const t = $("#toast");
    t.textContent = msg;
    t.className = "toast" + (kind ? " toast--" + kind : "");
    t.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => (t.hidden = true), 2600);
  }

  function save() {
    M.costbook.save(table);
    markDirty(false);
    toast("Master Costbook tersimpan. Dipakai pada perhitungan HPP.", "ok");
  }

  function reset() {
    M.costbook.reset();
    table = M.costbook.all();     // kembali ke seed default
    renderBody();
    markDirty(false);
    toast("Costbook dikembalikan ke nilai default.", "warn");
  }

  function init() {
    renderHead();
    renderBody();
    markDirty(false);
    $("#saveStatus").textContent = "Siap diedit";
    document.addEventListener("input", onInput);
    $("#btnSave").addEventListener("click", save);
    $("#btnReset").addEventListener("click", reset);
  }

  document.addEventListener("DOMContentLoaded", init);
})();

