input.content:
/* ============================================================
   costbook.js — Master Costbook Material (nilai/kg per material × gudang).
   Material (nama) dapat diedit, ditambah, dan dihapus. Nilai per gudang.
   Sumber & tujuan simpan: window.MOCK.costbook (localStorage), dipakai HPP.
   State internal berupa array baris berurutan supaya rename tidak menghilangkan
   data dan tidak bentrok saat dua baris sementara bernama sama.
   ============================================================ */
(() => {
  "use strict";

  const M = window.MOCK;
  const $ = (s, r = document) => r.querySelector(s);
  const num = (v) => { const n = parseFloat(v); return isNaN(n) ? null : n; };

  const WAREHOUSES = M.COSTBOOK_WAREHOUSES;   // [{key,label}]

  let seq = 0;
  const uid = () => `m${++seq}`;
  let rows = [];        // [{ id, name, rates: {unpack,wip,hold} }]
  let dirty = false;

  // Muat dari costbook tersimpan menjadi array baris
  function loadRows() {
    const table = M.costbook.all();     // { name: {gudang: nilai} }
    rows = Object.keys(table).map((name) => ({
      id: uid(),
      name,
      rates: WAREHOUSES.reduce((o, w) => (o[w.key] = table[name][w.key] != null ? table[name][w.key] : null, o), {}),
    }));
  }

  function markDirty(state) {
    dirty = state;
    const badge = $("#saveStatus");
    if (state) { badge.textContent = "Perubahan belum disimpan"; badge.className = "badge badge--draft"; }
    else { badge.textContent = "Tersimpan"; badge.className = "badge badge--done"; }
  }

  function renderHead() {
    $("#cbHeadRow").innerHTML =
      `<th>Material</th>` +
      WAREHOUSES.map((w) => `<th class="num">${w.label}<br /><small>Rp/kg</small></th>`).join("") +
      `<th></th>`;
  }

  function renderBody() {
    const body = $("#costbookTable tbody");
    body.innerHTML = rows.map((r) => {
      const cells = WAREHOUSES.map((w) => `
        <td class="num">
          <input type="number" min="0" step="1" class="cb-rate"
                 data-id="${r.id}" data-gudang="${w.key}"
                 value="${r.rates[w.key] != null ? r.rates[w.key] : ""}" placeholder="—" />
        </td>`).join("");
      return `<tr data-id="${r.id}">
        <td><input type="text" class="cb-name" data-id="${r.id}" value="${escAttr(r.name)}" placeholder="Nama material" /></td>
        ${cells}
        <td><button type="button" class="btn-icon" data-del="${r.id}" title="Hapus material">✕</button></td>
      </tr>`;
    }).join("") || `<tr><td colspan="${WAREHOUSES.length + 2}" class="empty">Belum ada material. Tambahkan dengan tombol di bawah.</td></tr>`;
  }

  function escAttr(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  }

  /* ---------- Events ---------- */
  function onInput(e) {
    const t = e.target;
    if (!t.dataset) return;
    if (t.classList.contains("cb-name")) {
      const r = rows.find((x) => x.id === t.dataset.id);
      if (r) { r.name = t.value; markDirty(true); }
    } else if (t.classList.contains("cb-rate")) {
      const r = rows.find((x) => x.id === t.dataset.id);
      if (r) { r.rates[t.dataset.gudang] = num(t.value); markDirty(true); }
    }
  }

  function onClick(e) {
    const del = e.target.dataset ? e.target.dataset.del : null;
    if (del) { rows = rows.filter((r) => r.id !== del); renderBody(); markDirty(true); }
  }

  function addMaterial() {
    rows.push({ id: uid(), name: "", rates: WAREHOUSES.reduce((o, w) => (o[w.key] = null, o), {}) });
    renderBody();
    markDirty(true);
    const last = $("#costbookTable tbody tr:last-child .cb-name");
    if (last) last.focus();
  }

  /* ---------- Simpan / Reset ---------- */
  function toTable() {
    // Array baris -> objek { name: {gudang: nilai} }. Nama kosong diabaikan;
    // nama duplikat: baris terakhir menang (diberi tahu lewat toast).
    const table = {};
    let skippedEmpty = 0, dupes = 0;
    rows.forEach((r) => {
      const name = (r.name || "").trim();
      if (!name) { skippedEmpty++; return; }
      if (table[name]) dupes++;
      table[name] = WAREHOUSES.reduce((o, w) => (o[w.key] = r.rates[w.key] != null ? r.rates[w.key] : null, o), {});
    });
    return { table, skippedEmpty, dupes };
  }

  let toastTimer = null;
  function toast(msg, kind = "") {
    const t = $("#toast");
    t.textContent = msg;
    t.className = "toast" + (kind ? " toast--" + kind : "");
    t.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => (t.hidden = true), 3200);
  }

  function save() {
    const { table, skippedEmpty, dupes } = toTable();
    M.costbook.save(table);
    // muat ulang dari tersimpan agar state & tampilan konsisten dengan yang dipakai HPP
    loadRows();
    renderBody();
    markDirty(false);
    let msg = "Master Costbook tersimpan. Dipakai pada perhitungan HPP.";
    if (skippedEmpty) msg += ` ${skippedEmpty} baris tanpa nama diabaikan.`;
    if (dupes) msg += ` ${dupes} nama duplikat digabung (nilai terakhir dipakai).`;
    toast(msg, dupes || skippedEmpty ? "warn" : "ok");
  }

  function reset() {
    M.costbook.reset();
    loadRows();        // kembali ke seed default
    renderBody();
    markDirty(false);
    toast("Costbook dikembalikan ke nilai & material default.", "warn");
  }

  function init() {
    renderHead();
    loadRows();
    renderBody();
    markDirty(false);
    $("#saveStatus").textContent = "Siap diedit";
    document.addEventListener("input", onInput);
    document.addEventListener("click", onClick);
    $("#btnSave").addEventListener("click", save);
    $("#btnReset").addEventListener("click", reset);
    const add = $("#btnAddMaterial");
    if (add) add.addEventListener("click", addMaterial);
  }

  document.addEventListener("DOMContentLoaded", init);
})();

