content.data:
const RATE = { manPower: 400, foh: 300, bahanPendukung: 500, consumables: 200, koordinasi: 200, scrapPct: 0.02 };

/* ---------- Master Costbook Material — nilai/kg PER MATERIAL × PER GUDANG (NFR-07b) ----------
   Gudang: unpack (Gudang Produksi 2), wip (Gudang WIP), hold (Gudang Material Hold).
   Material yang tercatat = material yang muncul pada baby coil (COILS).
   Nilai default di sini adalah seed; halaman Master Costbook dapat meng-override
   dan menyimpannya ke localStorage (key mockProduksi.costbook), terpisah dari session. */
const COSTBOOK_WAREHOUSES = [
  { key: "unpack", label: "Gudang Produksi 2 (Unpack)" },
  { key: "wip", label: "Gudang WIP" },
  { key: "hold", label: "Gudang Material Hold" },
];
// Daftar material master untuk costbook (tiga yang ada pada COILS)
const COSTBOOK_MATERIALS = [
  "Coil Galvanis 1.0mm",
  "Coil Galvanis 0.8mm",
  "Coil Cold Rolled 1.2mm",
];
// Seed default nilai/kg (Rp). null = belum ditetapkan.
const COSTBOOK_DEFAULT = {
  "Coil Galvanis 1.0mm":     { unpack: 14500, wip: 14200, hold: 13800 },
  "Coil Galvanis 0.8mm":     { unpack: 14300, wip: 14000, hold: 13600 },
  "Coil Cold Rolled 1.2mm":  { unpack: 15200, wip: 14900, hold: 14400 },
};

// Beberapa kode gudang lama memakai "prod2" untuk Unpack — petakan agar lookup tetap jalan.
const GUDANG_ALIAS = { prod2: "unpack", produksi2: "unpack" };
const normGudang = (g) => GUDANG_ALIAS[g] || g;

const COSTBOOK_KEY = "mockProduksi.costbook";
const costbook = {
  // Daftar material saat ini: dari tabel tersimpan bila ada, selain itu default.
  materials() {
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(COSTBOOK_KEY)); } catch (e) { saved = null; }
    const keys = saved && typeof saved === "object" ? Object.keys(saved) : [];
    return keys.length ? keys : COSTBOOK_MATERIALS.slice();
  },
  // Ambil seluruh tabel costbook (per material×gudang), dinormalkan ke semua gudang.
  // Bila ada data tersimpan, itu yang dipakai (mendukung rename/tambah material);
  // selain itu memakai seed default.
  all() {
    let saved = null;
    try { saved = JSON.parse(localStorage.getItem(COSTBOOK_KEY)); } catch (e) { saved = null; }
    const base = saved && typeof saved === "object" && Object.keys(saved).length ? saved : COSTBOOK_DEFAULT;
    const merged = {};
    Object.keys(base).forEach((mat) => {
      const row = base[mat] || {};
      merged[mat] = {};
      COSTBOOK_WAREHOUSES.forEach((w) => {
        merged[mat][w.key] = row[w.key] != null ? row[w.key] : null;
      });
    });
    return merged;
  },
  // Nilai/kg untuk satu material di satu gudang; menerima alias gudang lama.
  rate(material, gudang) {
    const g = normGudang(gudang);
    const row = costbook.all()[material];
    const v = row ? row[g] : null;
    return v != null ? v : 0;
  },
  save(table) { localStorage.setItem(COSTBOOK_KEY, JSON.stringify(table || {})); },
  reset() { localStorage.removeItem(COSTBOOK_KEY); },
};

/* ---------- Pilihan mesin / helper / setter (master) ---------- */
const MACHINES = ["Slitting Line 01", "Slitting Line 02", "Cut To Length 01"];
const HELPERS = ["Agus Pranoto", "Dedi Kurnia", "Rahmat Hidayat"];
const SETTERS = ["Joko Susilo", "Bambang W."];

/* ---------- User aktif (dummy; di sistem nyata dari sesi login) ---------- */
const CURRENT_USER = { name: "Budi S.", role: "Admin Produksi" };

/* ---------- Store lintas-halaman ---------- */

