 {coil:'c1',method:1,qty:60,total:1440,perPcs:0,selisih:0},
 {coil:'c2',method:2,qty:40,total:0,perPcs:24.2,selisih:0},
]};
// coilInfo map
const coilInfo={c1:{material:'Coil Galvanis 1.0mm',gudang:'unpack'},c2:{material:'Coil Galvanis 1.0mm',gudang:'wip'}};
