f.sources.forEach(s=>{ if(s.method===1) s.perPcs=s.qty>0?s.total/s.qty:0; else s.total=s.qty*s.perPcs; s.selisih=std>0?((s.perPcs-std)/std)*100:0; });
console.log('sumber1 perPcs=',f.sources[0].perPcs.toFixed(2),'selisih%=',f.sources[0].selisih.toFixed(2));
console.log('sumber2 total=',f.sources[1].total.toFixed(2),'selisih%=',f.sources[1].selisih.toFixed(2));
// fgRows split
const multi=f.sources.length>1;
const rows=f.sources.map(s=>{const info=coilInfo[s.coil];const label=multi&&info.gudang?f.productName+' ('+(SRC_LABEL[info.gudang]||info.gudang)+')':f.productName;
 return {produk:label,totalWeight:s.total,beratPcs:s.perPcs,qty:s.qty,material:info.material,gudang:info.gudang};});
