const kw1=[
 {material:'Coil Galvanis 1.0mm',gudang:'unpack',beratPcs:24,qty:60,total:1440},
 {material:'Coil Galvanis 1.0mm',gudang:'wip',beratPcs:24.2,qty:40,total:968},
];
const kw2=[]; // kosong
// scrap total
const scrapRows=[{weight:50}]; const scrapTot=50;
// sisa: none
const sisa=[];
// ==== komponen COGM (material per gudang asal) ====
function comp(rows){let o={material:0,mp:0,foh:0,bahan:0,cons:0,koor:0,scrap:0,total:0};rows.forEach(r=>{const cbv=cb(r.material,r.gudang);const mat=r.beratPcs*cbv;const sc=mat*RATE.scrapPct;const fp=mat+r.beratPcs*(RATE.manPower+RATE.foh+RATE.bahanPendukung+RATE.consumables+RATE.koordinasi)+sc;o.material+=mat*r.qty;o.total+=fp*r.qty;});return o;}
const t1=comp(kw1);
const material=t1.material;
const cogmTotal=t1.total; const fgTotal=t1.total;
// scrap inv/foh (unpack costbook 14500)
const scrapNilai=scrapTot*cb('Coil Galvanis 1.0mm','unpack');
const scrapInv=scrapNilai*0.4, scrapFoh=scrapNilai*0.6;
// ==== selisih per material×bucket ====
// packing: unpack 2450, wip 620
// terpakai kw1: unpack 1440, wip 968 ; scrap alloc: semua ke unpack (2% weight? no, scrap weight 50) -> proporsional unpack-only
// unpack packing tot=2450 -> semua scrap 50 ke unpack material
const selUnpackKg=2450-1440-0-50-0;   // packing-kw1-kw2-scrap-sisa
const selWipKg=620-968-0-0-0;
const selUnpackVal=selUnpackKg*cb('Coil Galvanis 1.0mm','unpack');
const selWipVal=selWipKg*cb('Coil Galvanis 1.0mm','wip');
const selVal=selUnpackVal+selWipVal;
console.log('selUnpack kg',selUnpackKg,'val',Math.round(selUnpackVal));
console.log('selWip kg',selWipKg,'val',Math.round(selWipVal));
console.log('selVal total',Math.round(selVal));
// material keluar (kredit)
const matUnpackHold=2450*cb('Coil Galvanis 1.0mm','unpack');
const matWip=620*cb('Coil Galvanis 1.0mm','wip');
// ==== susun debit/kredit (samakan dg hpp.js) ====
const mp=t1.mp,foh=t1.foh,bahan=t1.bahan,cons=t1.cons,koor=t1.koor,scrapPc=t1.scrap; // 0 krn comp tak isi detail; abaikan utk uji material-balance
let D=0,K=0;
D+=material; // COGM material
D+=scrapInv; // waste
D+=0; // sisa
D+=scrapFoh; // biaya scrap
D+= selVal>=0?selVal:0; // selisih debit
D+=fgTotal; // FG
K+=0; // loss
K+=matWip; K+=matUnpackHold;
K+= selVal<0? -selVal:0; // selisih kredit
K+=cogmTotal; // COGM
console.log('DEBIT',Math.round(D),'KREDIT',Math.round(K),'diff',Math.round(D-K));
"

